template <typename T>
T max_val(T a, T b) { return (a > b) ? a : b; }

// Full specialization for const char* (string comparison)
template <>
const char* max_val<const char*>(const char* a, const char* b) {
    return (std::strcmp(a, b) > 0) ? a : b;
}

// Usage examples
int i = max_val(5, 10);
const char* s = max_val("apple", "zebra"); // Uses specialization
float f = max_val(3.5f, 1.2f);
